def find_dotenv(
    filename: str = '.env',
    raise_error_if_not_found: bool = False,
    usecwd: bool = False,
) -> str:
    """
    Search in increasingly higher folders for the given file

    Returns path to the file if found, or an empty string otherwise
    """

    def _is_interactive():
        """ Decide whether this is running in a REPL or IPython notebook """
        try:
            main = __import__('__main__', None, None, fromlist=['__file__'])
        except ModuleNotFoundError:
            return False
        return not hasattr(main, '__file__')

    if usecwd or _is_interactive() or getattr(sys, 'frozen', False):
        # Should work without __file__, e.g. in REPL or IPython notebook.
        path = os.getcwd()
    else:
        # will work for .py files
        frame = sys._getframe()
        current_file = __file__

        while frame.f_code.co_filename == current_file:
            assert frame.f_back is not None
            frame = frame.f_back
        frame_filename = frame.f_code.co_filename

        # Check if the frame's filename is from a zip file
        if '.zip' in frame_filename and not os.path.isfile(frame_filename):
            # If called from inside a zip file, use the current working directory
            path = os.getcwd()
        else:
            path = os.path.dirname(os.path.abspath(frame_filename))

    try:
        for dirname in _walk_to_root(path):
            check_path = os.path.join(dirname, filename)
            if os.path.isfile(check_path):
                return check_path
    except IOError:
        # If _walk_to_root fails (e.g., with a zip file path), fall back to cwd
        if not usecwd:  # Only if we haven't already tried with cwd
            return find_dotenv(filename, raise_error_if_not_found, True)

    if raise_error_if_not_found:
        raise IOError('File not found')

    return ''
